Mesh<Point, double> result;
std::vector<Point> face_vertices;
std::vector<unsigned> face_indices;
std::vector<RT::Cell_handle> incident_cells;
std::vector<bool> visited(rt.number_of_edges(), false);

for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
    if (visited[eit->second + (eit->third << 2)]) continue;
    if (is_small_edge(rt, *eit, threshold)) continue;

    RT::Cell_handle cell = eit->first;
    int opposite_index = eit->third;
    RT::Cell_handle neighbor = cell->neighbor(opposite_index);
    incident_cells.clear();

    // Collect incident cells for the current edge
    incident_cells.push_back(cell);
    incident_cells.push_back(neighbor);
    visited[eit->second + (eit->third << 2)] = true;
    visited[opposite_index + (cell->index(neighbor) << 2)] = true;

    // Find all cells incident to the edge
    RT::Cell_circulator cc = rt.incident_cells(*eit);
    RT::Cell_circulator done = cc;
    do {
        if (!rt.is_infinite(cc)) {
            incident_cells.push_back(cc);
        }
        ++cc;
    } while (cc != done);

    // Remove duplicates and sort incident cells
    std::sort(incident_cells.begin(), incident_cells.end());
    incident_cells.erase(std::unique(incident_cells.begin(), incident_cells.end()), incident_cells.end());

    // Collect vertices of the power diagram face
    face_vertices.clear();
    face_indices.clear();
    for (auto const& c : incident_cells) {
        for (int i = 0; i < 4; ++i) {
            if (c->vertex(i) != rt.vertex(eit->second) && c->vertex(i) != rt.vertex(eit->third)) {
                Point p = c->vertex(i)->point().point();
                auto it = std::find(face_vertices.begin(), face_vertices.end(), p);
                if (it == face_vertices.end()) {
                    face_vertices.push_back(p);
                    face_indices.push_back(result.vertices.size());
                    result.vertices.push_back(p);
                } else {
                    face_indices.push_back(std::distance(face_vertices.begin(), it));
                }
            }
        }
    }

    // Calculate edge length as info
    double edge_length = std::sqrt(rt.segment(*eit).squared_length());
    result.push_back(face_indices, edge_length);
}

return result;

